struct Proposal {
  address target;
  bytes calldata_;
  uint256 snapshotBlock;
  uint256 voteEnd;
  uint256 forVotes;
  uint256 againstVotes;
}

function propose(address target, bytes calldata data) external {
  proposals[nextId] = Proposal(target, data, block.number,
    block.timestamp + VOTING_PERIOD, 0, 0);
}

function castVote(uint id, bool support) external {
  uint weight = token.getPastVotes(msg.sender, proposals[id].snapshotBlock);
  support ? proposals[id].forVotes += weight : proposals[id].againstVotes += weight;
}

function execute(uint id) external {
  Proposal storage p = proposals[id];
  require(block.timestamp > p.voteEnd, "still voting");
  require(p.forVotes + p.againstVotes >= quorum, "no quorum");
  require(p.forVotes > p.againstVotes, "not passed");
  target.call(p.calldata_);
}
